{"command":"$path = 'C:\Users\admin\Desktop\ta.csv'
$bytes = [System.IO.File]::ReadAllBytes($path)
$hasBom = $bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
$text = [System.IO.File]::ReadAllText($path, [System.Text.UTF8Encoding]::new($hasBom))
$newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
$lines = $text -split "`r?`n", -1
$hadTrailingNewline = $lines.Length -gt 0 -and $lines[-1] -eq ''
if ($hadTrailingNewline) { $lines = $lines[0..($lines.Length - 2)] }
$header = $lines[0]
$data = if ($lines.Length -gt 1) { $lines[1..($lines.Length - 1)] } else { @() }
$kept = @($header)
foreach ($line in $data) {
    if ($line -match '^(\d+),') {
        $id = [int]$Matches[1]
        if (($id -ge 1 -and $id -le 40) -or ($id -ge 10001 -and $id -le 10040)) {
            $kept += $line
        }
    }
}
$backup = "$path.bak_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
Copy-Item -LiteralPath $path -Destination $backup
$outText = [string]::Join($newline, $kept)
if ($hadTrailingNewline) { $outText += $newline }
[System.IO.File]::WriteAllText($path, $outText, [System.Text.UTF8Encoding]::new($hasBom))
[pscustomobject]@{
    Path = $path
    Backup = $backup
    OriginalDataRows = $data.Count
    KeptDataRows = $kept.Count - 1
    RemovedDataRows = $data.Count - ($kept.Count - 1)
    Utf8Bom = $hasBom
} | Format-List","timeout_ms":10000}

