{"command":"$path = 'C:\Users\admin\Desktop\ta.csv'
$bytes = [System.IO.File]::ReadAllBytes($path)
$hasBom = $bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
$enc = [System.Text.UTF8Encoding]::new($hasBom)
$text = [System.IO.File]::ReadAllText($path, $enc)
$newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
$lines = $text -split "`r?`n", -1
$hadTrailingNewline = $lines.Length -gt 0 -and $lines[-1] -eq ''
if ($hadTrailingNewline) { $lines = $lines[0..($lines.Length - 2)] }

$existing90000 = @($lines | Where-Object { $_ -match '^900\d{2},' })
if ($existing90000.Count -gt 0) {
    throw "已有 900xx 行，未写入，避免重复。数量: $($existing90000.Count)"
}

$templateRows = @($lines | Where-Object { $_ -match '^100(\d{2}),' -and [int]$Matches[1] -ge 1 -and [int]$Matches[1] -le 40 })
if ($templateRows.Count -ne 40) {
    throw "未找到完整的 10001-10040 模板行。找到: $($templateRows.Count)"
}

$newRows = foreach ($line in $templateRows) {
    if ($line -match '^(100(\d{2})),"100\2"(.*)$') {
        $suffix = $Matches[2]
        $rest = $Matches[3]
        $newId = "900$suffix"
        "$newId,""$newId""$rest" -replace 'Parameter=\d+', 'Parameter=10000'
    } else {
        throw "模板行格式不符合预期: $line"
    }
}

$backup = "$path.bak_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
Copy-Item -LiteralPath $path -Destination $backup
$outLines = @($lines + $newRows)
$outText = [string]::Join($newline, $outLines)
if ($hadTrailingNewline) { $outText += $newline }
[System.IO.File]::WriteAllText($path, $outText, $enc)

[pscustomobject]@{
    Path = $path
    Backup = $backup
    AddedRows = $newRows.Count
    FirstAdded = $newRows[0]
    LastAdded = $newRows[-1]
} | Format-List","timeout_ms":10000}

{"command":"$rows = Import-Csv -LiteralPath 'C:\Users\admin\Desktop\ta.csv'
$ids = $rows | ForEach-Object { [int]$_.ID }
$badRange = @($ids | Where-Object { -not (($_ -ge 1 -and $_ -le 40) -or ($_ -ge 10001 -and $_ -le 10040) -or ($_ -ge 90001 -and $_ -le 90040)) })
$rows900 = @($rows | Where-Object { [int]$_.ID -ge 90001 -and [int]$_.ID -le 90040 })
