{"command":"$path = 'C:\Users\admin\Desktop\ta.csv'
$bytes = [System.IO.File]::ReadAllBytes($path)
$hasBom = $bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
$enc = [System.Text.UTF8Encoding]::new($hasBom)
$text = [System.IO.File]::ReadAllText($path, $enc)
$newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
$lines = $text -split "`r?`n", -1
$hadTrailingNewline = $lines.Length -gt 0 -and $lines[-1] -eq ''
if ($hadTrailingNewline) { $lines = $lines[0..($lines.Length - 2)] }

function Get-ParamForId([int]$id) {
    $base = if ($id -ge 90001 -and $id -le 90040) { $id - 90000 } elseif ($id -ge 10001 -and $id -le 10040) { $id - 10000 } else { $id }
    if ($base -ge 1 -and $base -le 10) { $p = 500 }
    elseif ($base -ge 11 -and $base -le 20) { $p = 1000 }
    elseif ($base -ge 21 -and $base -le 30) { $p = 1500 }
    elseif ($base -ge 31 -and $base -le 40) { $p = 2000 }
    else { return $null }

    if ($id -ge 10001 -and $id -le 10040) { return $p * 2 }
    if ($id -ge 90001 -and $id -le 90040) { return 10000 }
    return $p
}

$changed = 0
$newLines = for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    if ($i -eq 0 -or $line -notmatch '^(\d+),') { $line; continue }

    $id = [int]$Matches[1]
    $param = Get-ParamForId $id
    if ($null -eq $param -or $line -like '*ItemID=8310035*') { $line; continue }

    $item = ",(Parameter=$param,ItemID=8310035,ItemNumMin=1,ItemNumMax=1)"
    if ($line -notmatch '\)\)"$') {
        throw "DropItemInfo 格式不符合预期，未写入: $line"
    }
    $changed++
    $line -replace '\)\)"$', "$item))`""
}

$backup = "$path.bak_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
Copy-Item -LiteralPath $path -Destination $backup
$outText = [string]::Join($newline, $newLines)
if ($hadTrailingNewline) { $outText += $newline }
[System.IO.File]::WriteAllText($path, $outText, $enc)

[pscustomobject]@{
    Path = $path
    Backup = $backup
    ChangedRows = $changed
    Utf8Bom = $hasBom
} | Format-List","timeout_ms":10000}

{"command":"$rows = Import-Csv -LiteralPath 'C:\Users\admin\Desktop\ta.csv'
$bad = @()
$dupes = @()
foreach ($row in $rows) {
    $id = [int]$row.ID
    $base = if ($id -ge 90001 -and $id -le 90040) { $id - 90000 } elseif ($id -ge 10001 -and $id -le 10040) { $id - 10000 } else { $id }
    if ($base -ge 1 -and $base -le 10) { $expected = 500 }
    elseif ($base -ge 11 -and $base -le 20) { $expected = 1000 }
    elseif ($base -ge 21 -and $base -le 30) { $expected = 1500 }
    elseif ($base -ge 31 -and $base -le 40) { $expected = 2000 }
    else { $bad += $row; continue }
    if ($id -ge 10001 -and $id -le 10040) { $expected *= 2 }
    if ($id -ge 90001 -and $id -le 90040) { $expected = 10000 }

    $matches = [regex]::Matches($row.DropItemInfo, "Parameter=$expected,ItemID=8310035,ItemNumMin=1,ItemNumMax=1")
    if ($matches.Count -ne 1) { $bad += $row }
    $all8310035 = [regex]::Matches($row.DropItemInfo, "ItemID=8310035")
    if ($all8310035.Count -ne 1) { $dupes += $row }
}

$sampleIds = @(1,10,11,20,21,30,31,40,10001,10011,10021,10031,90001,90011,90021,90031)
$samples = $rows | Where-Object { $sampleIds -contains [int]$_.ID } | Select-Object ID,DropItemInfo
[pscustomobject]@{
    DataRows = $rows.Count
    RowsWith8310035 = (@($rows | Where-Object { $_.DropItemInfo -like '*ItemID=8310035*' })).Count
    BadExpectedParameter = $bad.Count
    Duplicate8310035 = $dupes.Count
} | Format-List
$samples | Format-Table -AutoSize","timeout_ms":10000}

