{"command":"$current = 'C:\Users\admin\Desktop\ta.csv'
$sourceBackup = 'C:\Users\admin\Desktop\ta.csv.bak_20260705_160031'
$bytes = [System.IO.File]::ReadAllBytes($current)
$hasBom = $bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
$enc = [System.Text.UTF8Encoding]::new($hasBom)
$text = [System.IO.File]::ReadAllText($current, $enc)
$newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
$lines = $text -split "`r?`n", -1
$hadTrailingNewline = $lines.Length -gt 0 -and $lines[-1] -eq ''
if ($hadTrailingNewline) { $lines = $lines[0..($lines.Length - 2)] }

if (@($lines | Where-Object { $_ -match '^123,' }).Count -gt 0) {
    throw '当前 ta.csv 已存在 123 行，未重复添加。'
}

$sourceLine = Get-Content -LiteralPath $sourceBackup | Where-Object { $_ -match '^123,' } | Select-Object -First 1
if (-not $sourceLine) { throw '未能在备份里找到 123 行。' }

$backup = "$current.bak_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
Copy-Item -LiteralPath $current -Destination $backup
$outLines = @($lines[0], $sourceLine) + $lines[1..($lines.Count - 1)]
$outText = [string]::Join($newline, $outLines)
if ($hadTrailingNewline) { $outText += $newline }
[System.IO.File]::WriteAllText($current, $outText, $enc)

[pscustomobject]@{
    Backup = $backup
    AddedLine = $sourceLine
    DataRows = $outLines.Count - 1
} | Format-List","timeout_ms":10000}
